/**
 * Loader for the cross-language test vectors in `testdata/mpp/vectors.json`,
 * which are generated by the Go reference implementation. Kept beside the
 * tests that consume it so that every module checking interop reads the same
 * file through the same shapes.
 *
 * Test-only. This module reads from the filesystem, so it is deliberately
 * absent from the package's entry points and must never be imported by
 * anything that ships: the runtime targets include Workers, where there is
 * no `node:fs`.
 */

import { readFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export interface JcsVector {
  name: string;
  input: string;
  canonical: string;
  encoded: string;
}

export interface Base64Vector {
  name: string;
  bytes: number[];
  encoded: string;
}

export interface ChallengeIdVector {
  name: string;
  secret: string;
  realm: string;
  method: string;
  intent: string;
  request: string;
  expires: string;
  digest: string;
  opaque: string;
  hmacInput: string;
  id: string;
}

export interface ChallengeHeaderVector {
  name: string;
  params: {
    ID: string;
    Realm: string;
    Method: string;
    Intent: string;
    Request: string;
    Expires: string;
    Digest: string;
    Description: string;
    Opaque: string;
  };
  header: string;
}

export interface CredentialVector {
  name: string;
  header: string;
  json: string;
}

export interface ReceiptVector {
  name: string;
  header: string;
  json: string;
}

export interface GoVectors {
  jcs: JcsVector[];
  base64url: Base64Vector[];
  challengeId: ChallengeIdVector[];
  challengeHeaders: ChallengeHeaderVector[];
  credentials: CredentialVector[];
  receipts: ReceiptVector[];
}

/** Read and parse the Go-generated vector file. */
export async function loadGoVectors(): Promise<GoVectors> {
  const here = dirname(fileURLToPath(import.meta.url));
  const path = join(here, "..", "..", "testdata", "mpp", "vectors.json");
  return JSON.parse(await readFile(path, "utf-8")) as GoVectors;
}
